d.blocks.emplace(u8"N01", Block{u8"N01", 15, {}, {}, {u8"N01:0", u8"N01:1", u8"N01:2", u8"N01:3", u8"N01:4", u8"N01:5", u8"N01:6"}});
d.cues.emplace(u8"N01:0", Cue{u8"N01:0", u8"N01", CueKind::Speech, u8"joe", u8"A pol\u00edcia n\u00e3o vai subir at\u00e9 aqui. Temos alguns minutos.", u8"", 15, {}, {}, {}, u8""});
d.cues.emplace(u8"N01:1", Cue{u8"N01:1", u8"N01", CueKind::Speech, u8"bartholomeu", u8"A porta n\u00e3o fecha.", u8"", 15, {}, {}, {}, u8""});
d.cues.emplace(u8"N01:2", Cue{u8"N01:2", u8"N01", CueKind::Speech, u8"thomas", u8"Olha pra mim, pequeno. No tr\u00eas a gente empurra junto.", u8"", 15, {}, {}, {u8"bartholomeu"}, u8""});
d.cues.emplace(u8"N01:3", Cue{u8"N01:3", u8"N01", CueKind::Speech, u8"harley", u8"Voc\u00ea deixou isso. De novo.", u8"", 15, {}, {}, {}, u8""});
d.cues.emplace(u8"N01:4", Cue{u8"N01:4", u8"N01", CueKind::Speech, u8"joe", u8"Guarda. Conversamos l\u00e1 em cima.", u8"", 15, {}, {}, {u8"harley"}, u8""});
d.cues.emplace(u8"N01:5", Cue{u8"N01:5", u8"N01", CueKind::Speech, u8"harley", u8"Voc\u00ea sempre promete.", u8"", 15, {}, {}, {}, u8""});
d.cues.emplace(u8"N01:6", Cue{u8"N01:6", u8"N01", CueKind::Gesture, u8"", u8"", u8"thomas_checks_barth_hand", 15, {}, {}, {u8"thomas", u8"bartholomeu"}, u8""});
d.blocks.emplace(u8"N02", Block{u8"N02", 15, {}, {}, {u8"N02:0", u8"N02:1", u8"N02:2", u8"N02:3", u8"N02:4", u8"N02:5", u8"N02:6"}});
d.cues.emplace(u8"N02:0", Cue{u8"N02:0", u8"N02", CueKind::Speech, u8"thomas", u8"\u00c9 s\u00f3 um morcego fantasiado. Relaxa. Quando a gente sair, pago caf\u00e9 pra todo mundo.", u8"", 15, {}, {}, {}, u8"thomas_promised_coffee"});
d.cues.emplace(u8"N02:1", Cue{u8"N02:1", u8"N02", CueKind::Speech, u8"bartholomeu", u8"Voc\u00ea disse isso na \u00faltima vez.", u8"", 15, {}, {}, {u8"thomas"}, u8""});
d.cues.emplace(u8"N02:2", Cue{u8"N02:2", u8"N02", CueKind::Speech, u8"thomas", u8"Paguei, n\u00e3o paguei?", u8"", 15, {}, {}, {u8"bartholomeu"}, u8""});
d.cues.emplace(u8"N02:3", Cue{u8"N02:3", u8"N02", CueKind::Speech, u8"harley", u8"Eu n\u00e3o ficaria na janela.", u8"", 15, {}, {}, {}, u8""});
d.cues.emplace(u8"N02:4", Cue{u8"N02:4", u8"N02", CueKind::Speech, u8"joe", u8"Sai da\u00ed, Thomas.", u8"", 15, {}, {}, {u8"thomas"}, u8""});
d.cues.emplace(u8"N02:5", Cue{u8"N02:5", u8"N02", CueKind::Speech, u8"jack", u8"J\u00e1 cruzei com ele. Sa\u00ed vivo. A janela n\u00e3o \u00e9 o \u00fanico lugar por onde algu\u00e9m entra.", u8"", 15, {}, {}, {}, u8"jack_previous_encounter_heard"});
d.cues.emplace(u8"N02:6", Cue{u8"N02:6", u8"N02", CueKind::Gesture, u8"", u8"", u8"distant_batsignal", 15, {}, {}, {}, u8""});
d.blocks.emplace(u8"N03", Block{u8"N03", 15, {}, {}, {u8"N03:0", u8"N03:1", u8"N03:2", u8"N03:3"}});
d.cues.emplace(u8"N03:0", Cue{u8"N03:0", u8"N03", CueKind::Speech, u8"thomas", u8"Merda, que foi isso\u2014", u8"", 15, {}, {}, {}, u8""});
d.cues.emplace(u8"N03:1", Cue{u8"N03:1", u8"N03", CueKind::Speech, u8"joe", u8"Thomas?!", u8"", 15, {}, {}, {}, u8""});
d.cues.emplace(u8"N03:2", Cue{u8"N03:2", u8"N03", CueKind::Speech, u8"harley", u8"Barth, vem comigo. Joe, olha pra mim. Agora anda.", u8"", 15, {}, {}, {u8"bartholomeu"}, u8""});
d.cues.emplace(u8"N03:3", Cue{u8"N03:3", u8"N03", CueKind::Speech, u8"joe", u8"N\u00e3o foi a pol\u00edcia.", u8"", 15, {}, {}, {}, u8""});
d.blocks.emplace(u8"N04", Block{u8"N04", 15, {}, {}, {u8"N04:0", u8"N04:1"}});
d.cues.emplace(u8"N04:0", Cue{u8"N04:0", u8"N04", CueKind::Speech, u8"joe", u8"Foi o carrinho. Preciso sair daqui.", u8"", 15, {u8"joe_cart_noise_observed"}, {}, {}, u8""});
d.cues.emplace(u8"N04:1", Cue{u8"N04:1", u8"N04", CueKind::Gesture, u8"", u8"", u8"quiet_corridor", 15, {u8"quiet_corridor_observed"}, {}, {}, u8""});
d.blocks.emplace(u8"N05", Block{u8"N05", 15, {}, {}, {u8"N05:0", u8"N05:1", u8"N05:2"}});
d.cues.emplace(u8"N05:0", Cue{u8"N05:0", u8"N05", CueKind::Speech, u8"joe", u8"Ele passou aqui?", u8"", 15, {u8"ambiguous_trace_observed"}, {}, {}, u8""});
d.cues.emplace(u8"N05:1", Cue{u8"N05:1", u8"N05", CueKind::Speech, u8"joe", u8"Registro de frota. Vou guardar.", u8"", 15, {u8"doc01_read"}, {u8"doc05_read"}, {}, u8""});
d.cues.emplace(u8"N05:2", Cue{u8"N05:2", u8"N05", CueKind::Speech, u8"joe", u8"Uma das refer\u00eancias. Ainda preciso conferir as outras.", u8"", 15, {u8"doc01_read", u8"doc05_read"}, {}, {}, u8""});
d.blocks.emplace(u8"N06", Block{u8"N06", 15, {}, {}, {u8"N06:0", u8"N06:1"}});
d.cues.emplace(u8"N06:0", Cue{u8"N06:0", u8"N06", CueKind::Speech, u8"joe", u8"O mesmo cano. Esse andar volta para o outro lado.", u8"", 15, {u8"pipe_landmark_observed"}, {}, {}, u8""});
d.cues.emplace(u8"N06:1", Cue{u8"N06:1", u8"N06", CueKind::Gesture, u8"", u8"", u8"ambient_navigation", 15, {}, {}, {}, u8""});
d.blocks.emplace(u8"N07", Block{u8"N07", 15, {}, {}, {u8"N07:0", u8"N07:1", u8"N07:2", u8"N07:3", u8"N07:4", u8"N07:5", u8"N07:6", u8"N07:7"}});
d.cues.emplace(u8"N07:0", Cue{u8"N07:0", u8"N07", CueKind::Speech, u8"harley", u8"Voc\u00ea t\u00e1 sangrando.", u8"", 15, {u8"joe_bleeding"}, {}, {}, u8""});
d.cues.emplace(u8"N07:1", Cue{u8"N07:1", u8"N07", CueKind::Speech, u8"joe", u8"N\u00e3o \u00e9 nada.", u8"", 15, {u8"joe_bleeding"}, {}, {}, u8""});
d.cues.emplace(u8"N07:2", Cue{u8"N07:2", u8"N07", CueKind::Speech, u8"harley", u8"N\u00e3o mente pra mim. J\u00e1 vi voc\u00ea mentir melhor.", u8"", 15, {u8"joe_bleeding"}, {}, {}, u8""});
d.cues.emplace(u8"N07:3", Cue{u8"N07:3", u8"N07", CueKind::Speech, u8"harley", u8"Ouvi a porta bater, n\u00e3o vi quem entrou.", u8"", 15, {u8"harley_heard_unseen_door"}, {u8"joe_injured"}, {}, u8""});
d.cues.emplace(u8"N07:4", Cue{u8"N07:4", u8"N07", CueKind::Speech, u8"joe", u8"Voc\u00ea consegue andar?", u8"", 7, {u8"harley_injured"}, {}, {}, u8""});
d.cues.emplace(u8"N07:5", Cue{u8"N07:5", u8"N07", CueKind::Speech, u8"harley", u8"Consigo. Era s\u00f3 isso?", u8"", 7, {u8"harley_injured"}, {}, {}, u8""});
d.cues.emplace(u8"N07:6", Cue{u8"N07:6", u8"N07", CueKind::Speech, u8"joe", u8"Deixa eu ver. Se ficar pior, eu volto por voc\u00ea.", u8"", 8, {u8"harley_injured"}, {}, {}, u8""});
d.cues.emplace(u8"N07:7", Cue{u8"N07:7", u8"N07", CueKind::Speech, u8"harley", u8"Ent\u00e3o me diz por onde.", u8"", 8, {u8"harley_injured"}, {}, {}, u8""});
d.blocks.emplace(u8"N08", Block{u8"N08", 15, {}, {}, {u8"N08:0", u8"N08:1", u8"N08:2", u8"N08:3", u8"N08:4", u8"N08:5"}});
d.cues.emplace(u8"N08:0", Cue{u8"N08:0", u8"N08", CueKind::Speech, u8"jack", u8"Na primeira, veio pelo barulho. Na segunda, pela escada.", u8"", 15, {u8"jack_two_encounters_observed"}, {}, {}, u8""});
d.cues.emplace(u8"N08:1", Cue{u8"N08:1", u8"N08", CueKind::Speech, u8"joe", u8"Ele sabe o caminho?", u8"", 15, {u8"jack_two_encounters_observed"}, {}, {}, u8""});
d.cues.emplace(u8"N08:2", Cue{u8"N08:2", u8"N08", CueKind::Speech, u8"jack", u8"Sabe o que voc\u00ea mostrou.", u8"", 15, {u8"jack_two_encounters_observed"}, {}, {}, u8""});
d.cues.emplace(u8"N08:3", Cue{u8"N08:3", u8"N08", CueKind::Speech, u8"jack", u8"A porta est\u00e1 aberta. O resto \u00e9 palpite.", u8"", 15, {u8"jack_open_door_observed"}, {u8"jack_two_encounters_observed"}, {}, u8""});
d.cues.emplace(u8"N08:4", Cue{u8"N08:4", u8"N08", CueKind::Speech, u8"jack", u8"Esse hospital recebe muito bem.", u8"", 8, {u8"jack_heard_thomas_or_injury"}, {}, {}, u8""});
d.cues.emplace(u8"N08:5", Cue{u8"N08:5", u8"N08", CueKind::Gesture, u8"", u8"", u8"jack_j1_laugh", 8, {u8"jack_heard_thomas_or_injury"}, {}, {u8"jack"}, u8""});
d.blocks.emplace(u8"N09", Block{u8"N09", 15, {}, {}, {u8"N09:0", u8"N09:1", u8"N09:2"}});
d.cues.emplace(u8"N09:0", Cue{u8"N09:0", u8"N09", CueKind::Speech, u8"joe", u8"A hora est\u00e1 andando.", u8"", 15, {u8"live_feed_observed"}, {}, {}, u8""});
d.cues.emplace(u8"N09:1", Cue{u8"N09:1", u8"N09", CueKind::Speech, u8"joe", u8"O mesmo reflexo. Isso j\u00e1 aconteceu.", u8"", 15, {u8"loop_feed_observed"}, {}, {}, u8""});
d.cues.emplace(u8"N09:2", Cue{u8"N09:2", u8"N09", CueKind::Speech, u8"joe", u8"Nada de imagem.", u8"", 15, {u8"offline_feed_observed"}, {}, {}, u8""});
d.blocks.emplace(u8"N10", Block{u8"N10", 15, {}, {}, {u8"N10:0", u8"N10:1"}});
d.cues.emplace(u8"N10:0", Cue{u8"N10:0", u8"N10", CueKind::Speech, u8"joe", u8"A c\u00e2mera mostrou o que havia, n\u00e3o o que h\u00e1.", u8"", 15, {u8"camera_area_physically_checked"}, {}, {}, u8""});
d.cues.emplace(u8"N10:1", Cue{u8"N10:1", u8"N10", CueKind::Speech, u8"joe", u8"Pode ser antigo.", u8"", 15, {}, {u8"camera_area_physically_checked"}, {}, u8""});
d.blocks.emplace(u8"N11", Block{u8"N11", 15, {}, {}, {u8"N11:0", u8"N11:1"}});
d.cues.emplace(u8"N11:0", Cue{u8"N11:0", u8"N11", CueKind::Speech, u8"joe", u8"Pensa, Joe. Pensa.", u8"", 15, {}, {}, {}, u8""});
d.cues.emplace(u8"N11:1", Cue{u8"N11:1", u8"N11", CueKind::Gesture, u8"", u8"", u8"hunter_arrival_physical", 15, {}, {}, {}, u8""});
d.blocks.emplace(u8"N12", Block{u8"N12", 15, {}, {}, {u8"N12:0", u8"N12:1"}});
d.cues.emplace(u8"N12:0", Cue{u8"N12:0", u8"N12", CueKind::Speech, u8"joe", u8"Tem rem\u00e9dio. O caminho at\u00e9 ele \u00e9 o problema.", u8"", 15, {u8"joe_injured"}, {}, {}, u8""});
d.cues.emplace(u8"N12:1", Cue{u8"N12:1", u8"N12", CueKind::Speech, u8"joe", u8"Posso precisar disso depois.", u8"", 15, {}, {u8"joe_injured"}, {}, u8""});
d.blocks.emplace(u8"N13", Block{u8"N13", 15, {}, {}, {u8"N13:0"}});
d.cues.emplace(u8"N13:0", Cue{u8"N13:0", u8"N13", CueKind::Speech, u8"joe", u8"Tem carro. A chave ficou num cofre l\u00e1 em cima.", u8"", 15, {u8"doc04_read"}, {}, {}, u8""});
d.blocks.emplace(u8"N14", Block{u8"N14", 15, {}, {}, {u8"N14:0", u8"N14:1", u8"N14:2"}});
d.cues.emplace(u8"N14:0", Cue{u8"N14:0", u8"N14", CueKind::Speech, u8"joe", u8"Tr\u00eas refer\u00eancias. Leitos, arquivo, manuten\u00e7\u00e3o.", u8"", 15, {u8"doc05_read"}, {}, {}, u8""});
d.cues.emplace(u8"N14:1", Cue{u8"N14:1", u8"N14", CueKind::Speech, u8"joe", u8"Agora a chave.", u8"", 15, {u8"key_inside_safe_observed"}, {}, {}, u8""});
d.cues.emplace(u8"N14:2", Cue{u8"N14:2", u8"N14", CueKind::Speech, u8"joe", u8"N\u00e3o abriu. Preciso conferir.", u8"", 15, {u8"keypad_failure_observed"}, {}, {}, u8""});
d.blocks.emplace(u8"N15", Block{u8"N15", 15, {}, {}, {u8"N15:0", u8"N15:1", u8"N15:2", u8"N15:3", u8"N15:4", u8"N15:5", u8"N15:6", u8"N15:7", u8"N15:8"}});
d.cues.emplace(u8"N15:0", Cue{u8"N15:0", u8"N15", CueKind::Speech, u8"bartholomeu", u8"Vi uma entrada perto das bombas. N\u00e3o vi sa\u00edda. Voc\u00ea sempre me disse pra falar s\u00f3 do que vi, Joe.", u8"", 15, {u8"barth_tunnel_entry_observed"}, {}, {}, u8""});
d.cues.emplace(u8"N15:1", Cue{u8"N15:1", u8"N15", CueKind::Speech, u8"joe", u8"Vem mostrar.", u8"", 15, {u8"joe_requested_tunnel_guidance"}, {}, {}, u8""});
d.cues.emplace(u8"N15:2", Cue{u8"N15:2", u8"N15", CueKind::Speech, u8"joe", u8"Guarda isso pra voc\u00ea.", u8"", 15, {u8"joe_declined_tunnel_guidance"}, {}, {}, u8""});
d.cues.emplace(u8"N15:3", Cue{u8"N15:3", u8"N15", CueKind::Speech, u8"bartholomeu", u8"Eu vou lembrar. \u00c9 bom saber que voc\u00ea ainda confia em mim.", u8"", 15, {u8"joe_shared_ammo_with_bartholomeu"}, {}, {}, u8""});
d.cues.emplace(u8"N15:4", Cue{u8"N15:4", u8"N15", CueKind::Speech, u8"bartholomeu", u8"Pode estar morto, Joe. Eu n\u00e3o vi.", u8"", 3, {u8"thomas_discussed"}, {}, {}, u8""});
d.cues.emplace(u8"N15:5", Cue{u8"N15:5", u8"N15", CueKind::Speech, u8"bartholomeu", u8"Thomas morreu", u8"", 12, {u8"barth_informed_of_thomas_proof"}, {}, {}, u8""});
d.cues.emplace(u8"N15:6", Cue{u8"N15:6", u8"N15", CueKind::Speech, u8"jack", u8"At\u00e9 o hospital deve ter desistido de achar esse homem.", u8"", 8, {u8"jack_act3_encounter", u8"jack_heard_thomas_or_injury"}, {}, {}, u8""});
d.cues.emplace(u8"N15:7", Cue{u8"N15:7", u8"N15", CueKind::Speech, u8"joe", u8"N\u00e3o fala dele assim.", u8"", 8, {u8"jack_act3_encounter", u8"jack_heard_thomas_or_injury"}, {}, {u8"jack"}, u8""});
