d.cues.emplace(u8"DOC05:0", Cue{u8"DOC05:0", u8"DOC05", CueKind::Document, u8"", u8"Cofre da Administra\u00e7\u00e3o, porta ao lado da sala de arquivo. Sequ\u00eancia de seis d\u00edgitos: leitos \u2192 arquivo \u2192 manuten\u00e7\u00e3o. Conferir as tr\u00eas refer\u00eancias no local.", u8"", 15, {}, {}, {}, u8""});
