d.cues.emplace(u8"DOC06:0", Cue{u8"DOC06:0", u8"DOC06", CueKind::Document, u8"", u8"A linha pluvial continua al\u00e9m da casa de bombas. A entrada n\u00e3o aparece na planta de emerg\u00eancia; a v\u00e1lvula maior aponta para a deriva\u00e7\u00e3o antiga.", u8"", 15, {}, {}, {}, u8""});
d.blocks.emplace(u8"DOC07", Block{u8"DOC07", 15, {u8"F3_UTILITY"}, {}, {u8"DOC07:0"}});
d.cues.emplace(u8"DOC07:0", Cue{u8"DOC07:0", u8"DOC07", CueKind::Document, u8"", u8"Isolamento: acesso desviado para o corredor oeste ap\u00f3s fechamento da sala de cirurgia. A placa antiga n\u00e3o foi retirada.", u8"", 15, {}, {}, {}, u8""});
d.blocks.emplace(u8"DOC08", Block{u8"DOC08", 15, {u8"F1_RADIO"}, {}, {u8"DOC08:0"}});
d.cues.emplace(u8"DOC08:0", Cue{u8"DOC08:0", u8"DOC08", CueKind::Document, u8"", u8"R\u00e1dio de cobertura: bateria remov\u00edvel. Interfer\u00eancia na central de seguran\u00e7a. Contato n\u00e3o \u00e9 confirma\u00e7\u00e3o de pouso.", u8"", 15, {}, {}, {}, u8""});
d.blocks.emplace(u8"DOC09", Block{u8"DOC09", 15, {u8"F2_CAMERAS"}, {}, {u8"DOC09:0"}});
d.cues.emplace(u8"DOC09:0", Cue{u8"DOC09:0", u8"DOC09", CueKind::Document, u8"", u8"Ao perder quadro, o sistema pode repetir os \u00faltimos segundos gravados. Verifique rel\u00f3gio e continuidade antes de agir.", u8"", 15, {}, {}, {}, u8""});
d.blocks.emplace(u8"DOC10", Block{u8"DOC10", 15, {u8"F3_EXAMS"}, {}, {u8"DOC10:0"}});
d.cues.emplace(u8"DOC10:0", Cue{u8"DOC10:0", u8"DOC10", CueKind::Document, u8"", u8"Anexo: acesso pela janela de servi\u00e7o. Trava externa exige ferramenta de alavanca guardada no suprimento do 2\u00ba andar.", u8"", 15, {}, {}, {}, u8""});
d.blocks.emplace(u8"DOC11", Block{u8"DOC11", 15, {u8"F2_SERVER"}, {}, {u8"DOC11:0"}});
d.cues.emplace(u8"DOC11:0", Cue{u8"DOC11:0", u8"DOC11", CueKind::Document, u8"", u8"Sem energia, o comando de abertura do servidor fica indispon\u00edvel. Uma folha j\u00e1 aberta exige fechamento manual. O acesso pelo suprimento e servi\u00e7o n\u00e3o depende deste motor.", u8"", 15, {}, {}, {}, u8""});
d.blocks.emplace(u8"DOC12", Block{u8"DOC12", 15, {u8"F1_LOBBY"}, {}, {u8"DOC12:0"}});
d.cues.emplace(u8"DOC12:0", Cue{u8"DOC12:0", u8"DOC12", CueKind::Document, u8"", u8"Ordem externa: manter per\u00edmetro. Nenhuma entrada ou sa\u00edda pela recep\u00e7\u00e3o sem identifica\u00e7\u00e3o.", u8"", 15, {}, {}, {}, u8""});
d.blocks.emplace(u8"DOC13", Block{u8"DOC13", 15, {u8"F2_ARCHIVE"}, {}, {u8"DOC13:0"}});
d.cues.emplace(u8"DOC13:0", Cue{u8"DOC13:0", u8"DOC13", CueKind::Document, u8"", u8"Transfer\u00eancia cl\u00ednica 19\u2014. Origem: A\u2014KH\u2014M. Destino: ala de observa\u00e7\u00e3o. A assinatura foi removida do formul\u00e1rio.", u8"", 15, {}, {}, {}, u8""});
d.blocks.emplace(u8"DOC14", Block{u8"DOC14", 15, {u8"F3_HALL_W"}, {}, {u8"DOC14:0"}});
d.cues.emplace(u8"DOC14:0", Cue{u8"DOC14:0", u8"DOC14", CueKind::Document, u8"", u8"Ala de observa\u00e7\u00e3o / acesso de servi\u00e7o", u8"", 15, {}, {}, {}, u8""});
