d.blocks.emplace(u8"AUD01", Block{u8"AUD01", 15, {u8"F2_SECURITY", u8"F2_CAMERAS"}, {}, {u8"AUD01:0"}});
d.cues.emplace(u8"AUD01:0", Cue{u8"AUD01:0", u8"AUD01", CueKind::Recording, u8"recording", u8"A cl\u00ednica caiu de novo. O rel\u00f3gio est\u00e1 correndo, mas o quadro repete a cortina. Confere com os olhos antes de mandar algu\u00e9m l\u00e1.", u8"", 15, {}, {}, {}, u8""});
d.blocks.emplace(u8"AUD02", Block{u8"AUD02", 15, {u8"B1_GENERATOR", u8"B1_PUMP"}, {}, {u8"AUD02:0"}});
d.cues.emplace(u8"AUD02:0", Cue{u8"AUD02:0", u8"AUD02", CueKind::Recording, u8"recording", u8"Passa da bomba maior. Se o ar parar, pegou o bra\u00e7o morto. A corrente vem do ramal que segue.", u8"", 15, {}, {}, {}, u8""});
d.blocks.emplace(u8"AUD03", Block{u8"AUD03", 15, {u8"F1_SECURITY"}, {}, {u8"AUD03:0"}});
d.cues.emplace(u8"AUD03:0", Cue{u8"AUD03:0", u8"AUD03", CueKind::Recording, u8"recording", u8"A \u00faltima ala foi evacuada? N\u00e3o recebi lista. Se algu\u00e9m ainda estiver l\u00e1, n\u00e3o desliguem a linha.", u8"", 15, {}, {}, {}, u8""});
d.blocks.emplace(u8"AUD04", Block{u8"AUD04", 15, {u8"F1_RADIO", u8"F1_LOBBY"}, {}, {u8"AUD04:0"}});
d.cues.emplace(u8"AUD04:0", Cue{u8"AUD04:0", u8"AUD04", CueKind::Recording, u8"recording", u8"Per\u00edmetro mantido. Ningu\u00e9m pela recep\u00e7\u00e3o. Repito: n\u00e3o entrem no edif\u00edcio sem contato.", u8"", 15, {}, {}, {}, u8""});
d.blocks.emplace(u8"AUD05", Block{u8"AUD05", 15, {u8"F2_CAMERAS", u8"F2_SECURITY"}, {}, {u8"AUD05:0"}});
d.cues.emplace(u8"AUD05:0", Cue{u8"AUD05:0", u8"AUD05", CueKind::Recording, u8"recording", u8"A movimenta\u00e7\u00e3o mudou de andar. Confirme antes de concluir. Um ru\u00eddo n\u00e3o \u00e9 uma pessoa.", u8"", 15, {}, {}, {}, u8""});
d.blocks.emplace(u8"AUD06", Block{u8"AUD06", 15, {u8"B1_PUMP"}, {u8"barth_recording_found"}, {u8"AUD06:0"}});
d.cues.emplace(u8"AUD06:0", Cue{u8"AUD06:0", u8"AUD06", CueKind::Recording, u8"bartholomeu", u8"Joe, achei a casa de bombas. Vi uma entrada, n\u00e3o vi onde sai. Se ouvir isso, n\u00e3o me siga \u00e0s cegas.", u8"", 15, {}, {}, {}, u8""});
