d.cues.emplace(u8"SP_ROBIN:0", Cue{u8"SP_ROBIN:0", u8"SP_ROBIN", CueKind::Speech, u8"radio", u8"Estou nos t\u00faneis. O sinal aqui \u00e9 ruim.", u8"robin_brief_encounter", 15, {}, {}, {}, u8""});
d.blocks.emplace(u8"SP_ALFRED", Block{u8"SP_ALFRED", 15, {u8"F2_CAMERAS"}, {u8"appearance:alfred"}, {u8"SP_ALFRED:0"}});
d.cues.emplace(u8"SP_ALFRED:0", Cue{u8"SP_ALFRED:0", u8"SP_ALFRED", CueKind::Speech, u8"radio", u8"Senhor, esse pr\u00e9dio n\u00e3o est\u00e1 seguro.", u8"alfred_partial_radio", 15, {}, {}, {}, u8""});
d.blocks.emplace(u8"SP_GORDON", Block{u8"SP_GORDON", 15, {u8"F1_LOBBY"}, {u8"appearance:gordon"}, {u8"SP_GORDON:0"}});
d.cues.emplace(u8"SP_GORDON:0", Cue{u8"SP_GORDON:0", u8"SP_GORDON", CueKind::Speech, u8"radio", u8"O quarteir\u00e3o est\u00e1 isolado. Aguarde instru\u00e7\u00f5es.", u8"gordon_exterior_radio", 15, {}, {}, {}, u8""});
d.blocks.emplace(u8"SP_ORACLE", Block{u8"SP_ORACLE", 15, {u8"F2_SECURITY"}, {u8"appearance:oracle"}, {u8"SP_ORACLE:0"}});
d.cues.emplace(u8"SP_ORACLE:0", Cue{u8"SP_ORACLE:0", u8"SP_ORACLE", CueKind::Speech, u8"radio", u8"Seu sinal ficou inst\u00e1vel. Vou tentar outra frequ\u00eancia.", u8"oracle_partial_radio", 15, {}, {}, {}, u8""});
d.blocks.emplace(u8"SP_FLASH", Block{u8"SP_FLASH", 15, {u8"R_LEDGE"}, {u8"appearance:flash"}, {u8"SP_FLASH:0"}});
d.cues.emplace(u8"SP_FLASH:0", Cue{u8"SP_FLASH:0", u8"SP_FLASH", CueKind::Gesture, u8"", u8"", u8"flash_brief_reference", 15, {}, {}, {}, u8""});
d.blocks.emplace(u8"E_RARE_CONFRONTATION", Block{u8"E_RARE_CONFRONTATION", 15, {}, {}, {u8"E_RARE_CONFRONTATION:0"}});
d.cues.emplace(u8"E_RARE_CONFRONTATION:0", Cue{u8"E_RARE_CONFRONTATION:0", u8"E_RARE_CONFRONTATION", CueKind::Epilogue, u8"", u8"A resist\u00eancia durou pouco. Joe saiu ferido. O hospital ficou para tr\u00e1s.", u8"", 15, {}, {}, {}, u8""});
d.blocks.emplace(u8"E_RARE_DESTRUCTION", Block{u8"E_RARE_DESTRUCTION", 15, {}, {}, {u8"E_RARE_DESTRUCTION:0"}});
d.cues.emplace(u8"E_RARE_DESTRUCTION:0", Cue{u8"E_RARE_DESTRUCTION:0", u8"E_RARE_DESTRUCTION", CueKind::Epilogue, u8"", u8"O hospital cedeu. Joe sobreviveu, gravemente ferido. Ao amanhecer, a pol\u00edcia o encontrou e o prendeu. Ele n\u00e3o conseguiu confirmar o destino do Hunter sob os destro\u00e7os.", u8"", 15, {}, {}, {}, u8""});
d.blocks.emplace(u8"BAN01", Block{u8"BAN01", 15, {}, {}, {u8"BAN01:0", u8"BAN01:1", u8"BAN01:2"}});
d.cues.emplace(u8"BAN01:0", Cue{u8"BAN01:0", u8"BAN01", CueKind::Speech, u8"thomas", u8"Barth, sua m\u00e3o ficou presa?", u8"", 15, {}, {}, {}, u8""});
d.cues.emplace(u8"BAN01:1", Cue{u8"BAN01:1", u8"BAN01", CueKind::Speech, u8"bartholomeu", u8"N\u00e3o. S\u00f3 tremendo.", u8"", 15, {}, {}, {}, u8""});
d.cues.emplace(u8"BAN01:2", Cue{u8"BAN01:2", u8"BAN01", CueKind::Speech, u8"thomas", u8"Ent\u00e3o segura o outro lado. Eu seguro o peso.", u8"", 15, {}, {}, {}, u8""});
d.blocks.emplace(u8"BAN02", Block{u8"BAN02", 15, {}, {}, {u8"BAN02:0", u8"BAN02:1", u8"BAN02:2"}});
d.cues.emplace(u8"BAN02:0", Cue{u8"BAN02:0", u8"BAN02", CueKind::Speech, u8"harley", u8"Ei, irm\u00e3ozinho, respira pelo nariz.", u8"", 15, {}, {}, {}, u8""});
d.cues.emplace(u8"BAN02:1", Cue{u8"BAN02:1", u8"BAN02", CueKind::Speech, u8"bartholomeu", u8"Voc\u00ea fala assim toda vez que eu fico com medo.", u8"", 15, {}, {}, {}, u8""});
d.cues.emplace(u8"BAN02:2", Cue{u8"BAN02:2", u8"BAN02", CueKind::Speech, u8"harley", u8"E voc\u00ea ainda fica vivo toda vez. Olha que m\u00e9todo bom.", u8"", 15, {}, {}, {}, u8""});
d.blocks.emplace(u8"BAN03", Block{u8"BAN03", 15, {}, {}, {u8"BAN03:0", u8"BAN03:1", u8"BAN03:2"}});
d.cues.emplace(u8"BAN03:0", Cue{u8"BAN03:0", u8"BAN03", CueKind::Speech, u8"harley", u8"Voc\u00ea trouxe todo mundo para c\u00e1 sem saber a sa\u00edda?", u8"", 15, {}, {}, {}, u8""});
d.cues.emplace(u8"BAN03:1", Cue{u8"BAN03:1", u8"BAN03", CueKind::Speech, u8"joe", u8"Eu sabia como sair da rua.", u8"", 15, {}, {}, {}, u8""});
d.cues.emplace(u8"BAN03:2", Cue{u8"BAN03:2", u8"BAN03", CueKind::Speech, u8"harley", u8"Com voc\u00ea, metade de um plano sempre vira aventura.", u8"", 15, {}, {}, {}, u8""});
d.blocks.emplace(u8"BAN04", Block{u8"BAN04", 15, {}, {}, {u8"BAN04:0", u8"BAN04:1", u8"BAN04:2"}});
d.cues.emplace(u8"BAN04:0", Cue{u8"BAN04:0", u8"BAN04", CueKind::Speech, u8"thomas", u8"Quando amanhecer, quero uma mesa grande e caf\u00e9 para os cinco.", u8"", 15, {}, {}, {}, u8""});
d.cues.emplace(u8"BAN04:1", Cue{u8"BAN04:1", u8"BAN04", CueKind::Speech, u8"joe", u8"Voc\u00ea sempre planeja a sobremesa antes da fuga.", u8"", 15, {}, {}, {}, u8""});
d.cues.emplace(u8"BAN04:2", Cue{u8"BAN04:2", u8"BAN04", CueKind::Speech, u8"thomas", u8"Algu\u00e9m precisa planejar a parte boa.", u8"", 15, {}, {}, {}, u8""});
d.blocks.emplace(u8"BAN05", Block{u8"BAN05", 15, {}, {}, {u8"BAN05:0", u8"BAN05:1", u8"BAN05:2"}});
d.cues.emplace(u8"BAN05:0", Cue{u8"BAN05:0", u8"BAN05", CueKind::Speech, u8"jack", u8"J\u00e1 vi o morcego de perto. Sa\u00ed vivo. Ha.", u8"", 15, {}, {}, {}, u8"jack_previous_encounter_heard"});
d.cues.emplace(u8"BAN05:1", Cue{u8"BAN05:1", u8"BAN05", CueKind::Speech, u8"bartholomeu", u8"Por que voc\u00ea ri quando diz isso?", u8"", 15, {}, {}, {}, u8""});
d.cues.emplace(u8"BAN05:2", Cue{u8"BAN05:2", u8"BAN05", CueKind::Speech, u8"jack", u8"Porque funcionou. N\u00e3o pergunte o quanto corri.", u8"", 15, {}, {}, {}, u8""});
d.blocks.emplace(u8"BAN06", Block{u8"BAN06", 15, {}, {}, {u8"BAN06:0", u8"BAN06:1", u8"BAN06:2"}});
d.cues.emplace(u8"BAN06:0", Cue{u8"BAN06:0", u8"BAN06", CueKind::Speech, u8"jack", u8"Se os monitores ainda funcionam, podemos observar o corredor.", u8"", 15, {}, {}, {}, u8""});
d.cues.emplace(u8"BAN06:1", Cue{u8"BAN06:1", u8"BAN06", CueKind::Speech, u8"harley", u8"Boa ideia. Pena que foi voc\u00ea quem teve.", u8"", 15, {}, {}, {}, u8""});
d.cues.emplace(u8"BAN06:2", Cue{u8"BAN06:2", u8"BAN06", CueKind::Speech, u8"jack", u8"Guarde o elogio para quando estivermos fora.", u8"", 15, {}, {}, {}, u8""});
d.blocks.emplace(u8"BAN07", Block{u8"BAN07", 15, {}, {}, {u8"BAN07:0", u8"BAN07:1", u8"BAN07:2"}});
d.cues.emplace(u8"BAN07:0", Cue{u8"BAN07:0", u8"BAN07", CueKind::Speech, u8"bartholomeu", u8"Eu sabia que voc\u00ea escolheria a escada de servi\u00e7o.", u8"", 15, {}, {}, {}, u8""});
d.cues.emplace(u8"BAN07:1", Cue{u8"BAN07:1", u8"BAN07", CueKind::Speech, u8"joe", u8"Voc\u00ea lembra melhor dos meus atalhos do que eu.", u8"", 15, {}, {}, {}, u8""});
d.cues.emplace(u8"BAN07:2", Cue{u8"BAN07:2", u8"BAN07", CueKind::Speech, u8"bartholomeu", u8"\u00c9 por isso que ainda ando com voc\u00ea.", u8"", 15, {}, {}, {}, u8""});
d.blocks.emplace(u8"BAN08", Block{u8"BAN08", 15, {}, {}, {u8"BAN08:0", u8"BAN08:1", u8"BAN08:2"}});
d.cues.emplace(u8"BAN08:0", Cue{u8"BAN08:0", u8"BAN08", CueKind::Speech, u8"thomas", u8"Se aquele sinal \u00e9 pra gente, eu fa\u00e7o o discurso.", u8"", 15, {}, {}, {}, u8""});
d.cues.emplace(u8"BAN08:1", Cue{u8"BAN08:1", u8"BAN08", CueKind::Speech, u8"harley", u8"Voc\u00ea faz cara de dur\u00e3o. Eu fa\u00e7o voc\u00ea sair da janela.", u8"", 15, {}, {}, {}, u8""});
d.cues.emplace(u8"BAN08:2", Cue{u8"BAN08:2", u8"BAN08", CueKind::Speech, u8"thomas", u8"Fechado, chefe.", u8"", 15, {}, {}, {}, u8""});
d.blocks.emplace(u8"BAN09", Block{u8"BAN09", 15, {}, {}, {u8"BAN09:0", u8"BAN09:1", u8"BAN09:2"}});
d.cues.emplace(u8"BAN09:0", Cue{u8"BAN09:0", u8"BAN09", CueKind::Speech, u8"harley", u8"Voc\u00ea est\u00e1 contando as portas ou evitando olhar pra mim?", u8"", 15, {}, {}, {}, u8""});
d.cues.emplace(u8"BAN09:1", Cue{u8"BAN09:1", u8"BAN09", CueKind::Speech, u8"joe", u8"As portas.", u8"", 15, {}, {}, {}, u8""});
d.cues.emplace(u8"BAN09:2", Cue{u8"BAN09:2", u8"BAN09", CueKind::Speech, u8"harley", u8"Eu sabia. Estava torcendo pela outra resposta.", u8"", 15, {}, {}, {}, u8""});
d.blocks.emplace(u8"BAN10", Block{u8"BAN10", 15, {}, {}, {u8"BAN10:0", u8"BAN10:1", u8"BAN10:2"}});
d.cues.emplace(u8"BAN10:0", Cue{u8"BAN10:0", u8"BAN10", CueKind::Speech, u8"bartholomeu", u8"Eu devia ter puxado o Thomas.", u8"", 15, {}, {}, {}, u8""});
d.cues.emplace(u8"BAN10:1", Cue{u8"BAN10:1", u8"BAN10", CueKind::Speech, u8"harley", u8"Voc\u00ea mal conseguia ficar de p\u00e9. N\u00e3o p\u00f5e isso nas suas costas.", u8"", 15, {}, {}, {}, u8""});
d.cues.emplace(u8"BAN10:2", Cue{u8"BAN10:2", u8"BAN10", CueKind::Speech, u8"bartholomeu", u8"Ele n\u00e3o teria deixado ningu\u00e9m para tr\u00e1s.", u8"", 15, {}, {}, {}, u8""});
d.blocks.emplace(u8"BAN11", Block{u8"BAN11", 15, {}, {}, {u8"BAN11:0", u8"BAN11:1", u8"BAN11:2"}});
d.cues.emplace(u8"BAN11:0", Cue{u8"BAN11:0", u8"BAN11", CueKind::Speech, u8"jack", u8"Na outra vez, o morcego esperou meu ru\u00eddo passar. Eu sa\u00ed vivo quando parei de repetir o caminho. Ha.", u8"", 15, {}, {}, {}, u8"jack_previous_encounter_heard"});
d.cues.emplace(u8"BAN11:1", Cue{u8"BAN11:1", u8"BAN11", CueKind::Speech, u8"joe", u8"Voc\u00ea riu daquela vez tamb\u00e9m?", u8"", 15, {}, {}, {}, u8""});
d.cues.emplace(u8"BAN11:2", Cue{u8"BAN11:2", u8"BAN11", CueKind::Speech, u8"jack", u8"Depois. Bem depois.", u8"", 15, {}, {}, {}, u8""});
d.blocks.emplace(u8"BAN12", Block{u8"BAN12", 15, {}, {}, {u8"BAN12:0", u8"BAN12:1", u8"BAN12:2"}});
d.cues.emplace(u8"BAN12:0", Cue{u8"BAN12:0", u8"BAN12", CueKind::Speech, u8"bartholomeu", u8"Joe, aquela hist\u00f3ria dos Wayne... voc\u00ea nunca terminou de contar.", u8"", 15, {}, {}, {}, u8""});
d.cues.emplace(u8"BAN12:1", Cue{u8"BAN12:1", u8"BAN12", CueKind::Speech, u8"joe", u8"N\u00e3o tem final bom. Quando comecei nessa vida, matei um casal da fam\u00edlia Wayne. O filho estava l\u00e1.", u8"", 15, {}, {}, {}, u8""});
d.cues.emplace(u8"BAN12:2", Cue{u8"BAN12:2", u8"BAN12", CueKind::Speech, u8"bartholomeu", u8"Voc\u00ea fala baixo agora. Eu queria que tivesse pensado nele antes.", u8"", 15, {}, {}, {}, u8""});
d.blocks.emplace(u8"BAN13", Block{u8"BAN13", 15, {}, {}, {u8"BAN13:0", u8"BAN13:1", u8"BAN13:2"}});
d.cues.emplace(u8"BAN13:0", Cue{u8"BAN13:0", u8"BAN13", CueKind::Speech, u8"harley", u8"Voc\u00ea nunca fala daquele casal Wayne quando tem luz acesa.", u8"", 15, {}, {}, {}, u8""});
d.cues.emplace(u8"BAN13:1", Cue{u8"BAN13:1", u8"BAN13", CueKind::Speech, u8"joe", u8"Matei os pais de um garoto. Apagar a luz n\u00e3o apaga isso.", u8"", 15, {}, {}, {}, u8""});
d.cues.emplace(u8"BAN13:2", Cue{u8"BAN13:2", u8"BAN13", CueKind::Speech, u8"harley", u8"Ainda bem que voc\u00ea sabe. S\u00f3 n\u00e3o usa culpa como desculpa para abandonar quem est\u00e1 aqui.", u8"", 15, {}, {}, {}, u8""});
d.blocks.emplace(u8"BAN14", Block{u8"BAN14", 15, {}, {}, {u8"BAN14:0", u8"BAN14:1", u8"BAN14:2"}});
d.cues.emplace(u8"BAN14:0", Cue{u8"BAN14:0", u8"BAN14", CueKind::Speech, u8"jack", u8"A c\u00e2mera repete o mesmo reflexo. Algu\u00e9m quer que acreditemos nela.", u8"", 15, {}, {}, {}, u8""});
d.cues.emplace(u8"BAN14:1", Cue{u8"BAN14:1", u8"BAN14", CueKind::Speech, u8"harley", u8"Voc\u00ea pode estar certo. Eu detesto quando acontece.", u8"", 15, {}, {}, {}, u8""});
d.cues.emplace(u8"BAN14:2", Cue{u8"BAN14:2", u8"BAN14", CueKind::Speech, u8"jack", u8"Olhe o rel\u00f3gio. Depois pode me detestar de novo.", u8"", 15, {}, {}, {}, u8""});
d.blocks.emplace(u8"BAN15", Block{u8"BAN15", 15, {}, {}, {u8"BAN15:0", u8"BAN15:1", u8"BAN15:2"}});
d.cues.emplace(u8"BAN15:0", Cue{u8"BAN15:0", u8"BAN15", CueKind::Speech, u8"bartholomeu", u8"A gente sa\u00eda dos apertos conversando. Hoje voc\u00ea s\u00f3 aponta portas.", u8"", 15, {}, {}, {}, u8""});
d.cues.emplace(u8"BAN15:1", Cue{u8"BAN15:1", u8"BAN15", CueKind::Speech, u8"joe", u8"Se eu falar demais, voc\u00ea ouve que estou com medo.", u8"", 15, {}, {}, {}, u8""});
d.cues.emplace(u8"BAN15:2", Cue{u8"BAN15:2", u8"BAN15", CueKind::Speech, u8"bartholomeu", u8"Eu j\u00e1 ouvi. Ainda estou do seu lado.", u8"", 15, {}, {}, {}, u8""});
d.blocks.emplace(u8"BAN16", Block{u8"BAN16", 15, {}, {}, {u8"BAN16:0", u8"BAN16:1", u8"BAN16:2", u8"BAN16:3"}});
d.cues.emplace(u8"BAN16:0", Cue{u8"BAN16:0", u8"BAN16", CueKind::Speech, u8"harley", u8"Barth, sua m\u00e3o parou de tremer?", u8"", 15, {}, {}, {}, u8""});
d.cues.emplace(u8"BAN16:1", Cue{u8"BAN16:1", u8"BAN16", CueKind::Speech, u8"bartholomeu", u8"S\u00f3 quando seguro alguma coisa.", u8"", 15, {}, {}, {}, u8""});
d.cues.emplace(u8"BAN16:2", Cue{u8"BAN16:2", u8"BAN16", CueKind::Speech, u8"harley", u8"Joe, conversa com seu amigo um minuto.", u8"", 15, {}, {}, {}, u8""});
d.cues.emplace(u8"BAN16:3", Cue{u8"BAN16:3", u8"BAN16", CueKind::Speech, u8"joe", u8"Estou ouvindo, Barth.", u8"", 15, {}, {}, {}, u8""});
d.blocks.emplace(u8"BAN17", Block{u8"BAN17", 15, {}, {}, {u8"BAN17:0", u8"BAN17:1", u8"BAN17:2"}});
d.cues.emplace(u8"BAN17:0", Cue{u8"BAN17:0", u8"BAN17", CueKind::Speech, u8"jack", u8"O quadro da garagem parou. Repare no mesmo gotejo.", u8"", 15, {}, {}, {}, u8""});
d.cues.emplace(u8"BAN17:1", Cue{u8"BAN17:1", u8"BAN17", CueKind::Speech, u8"joe", u8"Ent\u00e3o n\u00e3o sabemos quem est\u00e1 l\u00e1.", u8"", 15, {}, {}, {}, u8""});
d.cues.emplace(u8"BAN17:2", Cue{u8"BAN17:2", u8"BAN17", CueKind::Speech, u8"jack", u8"Agora voc\u00ea sabe exatamente o que n\u00e3o sabe.", u8"", 15, {}, {}, {}, u8""});
d.blocks.emplace(u8"BAN18", Block{u8"BAN18", 15, {}, {}, {u8"BAN18:0", u8"BAN18:1", u8"BAN18:2"}});
d.cues.emplace(u8"BAN18:0", Cue{u8"BAN18:0", u8"BAN18", CueKind::Speech, u8"jack", u8"Bartholomeu, voc\u00ea viu uma passagem?", u8"", 15, {}, {}, {}, u8""});
d.cues.emplace(u8"BAN18:1", Cue{u8"BAN18:1", u8"BAN18", CueKind::Speech, u8"bartholomeu", u8"Vi uma porta. N\u00e3o o outro lado.", u8"", 15, {}, {}, {}, u8""});
d.cues.emplace(u8"BAN18:2", Cue{u8"BAN18:2", u8"BAN18", CueKind::Speech, u8"harley", u8"Ele respondeu. N\u00e3o come\u00e7a a completar a hist\u00f3ria por ele, Jack.", u8"", 15, {}, {}, {}, u8""});
d.blocks.emplace(u8"BAN19", Block{u8"BAN19", 15, {}, {}, {u8"BAN19:0", u8"BAN19:1", u8"BAN19:2"}});
d.cues.emplace(u8"BAN19:0", Cue{u8"BAN19:0", u8"BAN19", CueKind::Speech, u8"harley", u8"Voc\u00ea chama isso de plano ou de pilha de pap\u00e9is?", u8"", 15, {}, {}, {}, u8""});
d.cues.emplace(u8"BAN19:1", Cue{u8"BAN19:1", u8"BAN19", CueKind::Speech, u8"joe", u8"Chamo de mais uma chance.", u8"", 15, {}, {}, {}, u8""});
d.cues.emplace(u8"BAN19:2", Cue{u8"BAN19:2", u8"BAN19", CueKind::Speech, u8"harley", u8"Ent\u00e3o guarda uma chance pra quem est\u00e1 vindo atr\u00e1s.", u8"", 15, {}, {}, {}, u8""});
d.blocks.emplace(u8"BAN20", Block{u8"BAN20", 15, {}, {}, {u8"BAN20:0", u8"BAN20:1", u8"BAN20:2"}});
d.cues.emplace(u8"BAN20:0", Cue{u8"BAN20:0", u8"BAN20", CueKind::Speech, u8"bartholomeu", u8"A bomba maior vibra diferente. Por ali o ar continua.", u8"", 15, {}, {}, {}, u8""});
d.cues.emplace(u8"BAN20:1", Cue{u8"BAN20:1", u8"BAN20", CueKind::Speech, u8"joe", u8"Voc\u00ea reparou antes de mim.", u8"", 15, {}, {}, {}, u8""});
d.cues.emplace(u8"BAN20:2", Cue{u8"BAN20:2", u8"BAN20", CueKind::Speech, u8"bartholomeu", u8"Fico olhando sa\u00edda at\u00e9 quando falo com voc\u00ea.", u8"", 15, {}, {}, {}, u8""});
d.blocks.emplace(u8"BAN21", Block{u8"BAN21", 15, {}, {}, {u8"BAN21:0", u8"BAN21:1", u8"BAN21:2"}});
d.cues.emplace(u8"BAN21:0", Cue{u8"BAN21:0", u8"BAN21", CueKind::Speech, u8"jack", u8"O servidor fecha com a energia ca\u00edda. O suprimento n\u00e3o usa o mesmo motor.", u8"", 15, {}, {}, {}, u8""});
d.cues.emplace(u8"BAN21:1", Cue{u8"BAN21:1", u8"BAN21", CueKind::Speech, u8"joe", u8"Voc\u00ea conferiu ou est\u00e1 apostando?", u8"", 15, {}, {}, {}, u8""});
d.cues.emplace(u8"BAN21:2", Cue{u8"BAN21:2", u8"BAN21", CueKind::Speech, u8"jack", u8"Conferi a placa. A porta ainda pode emperrar.", u8"", 15, {}, {}, {}, u8""});
d.blocks.emplace(u8"BAN22", Block{u8"BAN22", 15, {}, {}, {u8"BAN22:0", u8"BAN22:1", u8"BAN22:2"}});
d.cues.emplace(u8"BAN22:0", Cue{u8"BAN22:0", u8"BAN22", CueKind::Speech, u8"bartholomeu", u8"Pode usar o rem\u00e9dio. Sua m\u00e3o est\u00e1 pior.", u8"", 15, {}, {}, {}, u8""});
d.cues.emplace(u8"BAN22:1", Cue{u8"BAN22:1", u8"BAN22", CueKind::Speech, u8"harley", u8"Voc\u00ea tem pulso acelerado e est\u00e1 mentindo.", u8"", 15, {}, {}, {}, u8""});
d.cues.emplace(u8"BAN22:2", Cue{u8"BAN22:2", u8"BAN22", CueKind::Speech, u8"bartholomeu", u8"Aprendi com o Joe. P\u00e9ssimo professor.", u8"", 15, {}, {}, {}, u8""});
d.blocks.emplace(u8"BAN23", Block{u8"BAN23", 15, {}, {}, {u8"BAN23:0", u8"BAN23:1", u8"BAN23:2"}});
d.cues.emplace(u8"BAN23:0", Cue{u8"BAN23:0", u8"BAN23", CueKind::Speech, u8"harley", u8"Eu te sigo porque escolho. N\u00e3o porque voc\u00ea manda.", u8"", 15, {}, {}, {}, u8""});
d.cues.emplace(u8"BAN23:1", Cue{u8"BAN23:1", u8"BAN23", CueKind::Speech, u8"joe", u8"Eu sei.", u8"", 15, {}, {}, {}, u8""});
d.cues.emplace(u8"BAN23:2", Cue{u8"BAN23:2", u8"BAN23", CueKind::Speech, u8"harley", u8"Ent\u00e3o pergunta antes de me deixar segurando a porta.", u8"", 15, {}, {}, {}, u8""});
d.blocks.emplace(u8"BAN24", Block{u8"BAN24", 15, {}, {}, {u8"BAN24:0", u8"BAN24:1", u8"BAN24:2"}});
d.cues.emplace(u8"BAN24:0", Cue{u8"BAN24:0", u8"BAN24", CueKind::Speech, u8"jack", u8"Se ele ouviu a escada, pode chegar por cima. Pode.", u8"", 15, {}, {}, {}, u8""});
d.cues.emplace(u8"BAN24:1", Cue{u8"BAN24:1", u8"BAN24", CueKind::Speech, u8"bartholomeu", u8"Voc\u00ea nunca diz uma coisa boa?", u8"", 15, {}, {}, {}, u8""});
d.cues.emplace(u8"BAN24:2", Cue{u8"BAN24:2", u8"BAN24", CueKind::Speech, u8"jack", u8"A boa \u00e9 que ainda temos outra escada. Ha.", u8"", 15, {}, {}, {}, u8""});
d.blocks.emplace(u8"BAN25", Block{u8"BAN25", 15, {}, {}, {u8"BAN25:0", u8"BAN25:1", u8"BAN25:2"}});
d.cues.emplace(u8"BAN25:0", Cue{u8"BAN25:0", u8"BAN25", CueKind::Speech, u8"bartholomeu", u8"Voc\u00ea me tirou de uma briga na rua anos atr\u00e1s.", u8"", 15, {}, {}, {}, u8""});
d.cues.emplace(u8"BAN25:1", Cue{u8"BAN25:1", u8"BAN25", CueKind::Speech, u8"joe", u8"Voc\u00ea pagou de volta umas dez vezes.", u8"", 15, {}, {}, {}, u8""});
d.cues.emplace(u8"BAN25:2", Cue{u8"BAN25:2", u8"BAN25", CueKind::Speech, u8"bartholomeu", u8"Amigos n\u00e3o fazem conta. Voc\u00ea que me ensinou.", u8"", 15, {}, {}, {}, u8""});
d.blocks.emplace(u8"BAN26", Block{u8"BAN26", 15, {}, {}, {u8"BAN26:0", u8"BAN26:1", u8"BAN26:2"}});
d.cues.emplace(u8"BAN26:0", Cue{u8"BAN26:0", u8"BAN26", CueKind::Speech, u8"jack", u8"Mudei para outra c\u00e2mera. Essa ainda est\u00e1 viva.", u8"", 15, {}, {}, {}, u8""});
d.cues.emplace(u8"BAN26:1", Cue{u8"BAN26:1", u8"BAN26", CueKind::Speech, u8"harley", u8"Mostra a hora. N\u00e3o me vende corredor vazio gravado.", u8"", 15, {}, {}, {}, u8""});
d.cues.emplace(u8"BAN26:2", Cue{u8"BAN26:2", u8"BAN26", CueKind::Speech, u8"joe", u8"Ela tem raz\u00e3o. A gente confere o caminho.", u8"", 15, {}, {}, {}, u8""});
d.blocks.emplace(u8"BAN27", Block{u8"BAN27", 15, {}, {}, {u8"BAN27:0", u8"BAN27:1", u8"BAN27:2"}});
d.cues.emplace(u8"BAN27:0", Cue{u8"BAN27:0", u8"BAN27", CueKind::Speech, u8"harley", u8"Se eu disser corre, voc\u00ea corre primeiro.", u8"", 15, {}, {}, {}, u8""});
d.cues.emplace(u8"BAN27:1", Cue{u8"BAN27:1", u8"BAN27", CueKind::Speech, u8"bartholomeu", u8"N\u00e3o vou te deixar sozinha.", u8"", 15, {}, {}, {}, u8""});
d.cues.emplace(u8"BAN27:2", Cue{u8"BAN27:2", u8"BAN27", CueKind::Speech, u8"harley", u8"Ent\u00e3o corre comigo, irm\u00e3ozinho.", u8"", 15, {}, {}, {}, u8""});
d.blocks.emplace(u8"BAN28", Block{u8"BAN28", 15, {}, {}, {u8"BAN28:0", u8"BAN28:1", u8"BAN28:2"}});
d.cues.emplace(u8"BAN28:0", Cue{u8"BAN28:0", u8"BAN28", CueKind::Speech, u8"harley", u8"Voc\u00ea pensou em pular sozinho, n\u00e3o pensou?", u8"", 15, {}, {}, {}, u8""});
d.cues.emplace(u8"BAN28:1", Cue{u8"BAN28:1", u8"BAN28", CueKind::Speech, u8"joe", u8"Pensei em ver onde cai.", u8"", 15, {}, {}, {}, u8""});
d.cues.emplace(u8"BAN28:2", Cue{u8"BAN28:2", u8"BAN28", CueKind::Speech, u8"harley", u8"Olha tamb\u00e9m quem consegue atravessar. Eu n\u00e3o sou uma mala.", u8"", 15, {}, {}, {}, u8""});
d.blocks.emplace(u8"BAN29", Block{u8"BAN29", 7, {}, {}, {u8"BAN29:0", u8"BAN29:1", u8"BAN29:2"}});
d.cues.emplace(u8"BAN29:0", Cue{u8"BAN29:0", u8"BAN29", CueKind::Speech, u8"harley", u8"Eu cuido de voc\u00ea h\u00e1 anos. Hoje eu precisei pedir duas vezes.", u8"", 15, {}, {}, {}, u8""});
d.cues.emplace(u8"BAN29:1", Cue{u8"BAN29:1", u8"BAN29", CueKind::Speech, u8"joe", u8"Eu ouvi na primeira.", u8"", 15, {}, {}, {}, u8""});
d.cues.emplace(u8"BAN29:2", Cue{u8"BAN29:2", u8"BAN29", CueKind::Speech, u8"harley", u8"Ouvir e voltar s\u00e3o coisas diferentes.", u8"", 15, {}, {}, {}, u8""});
d.blocks.emplace(u8"BAN30", Block{u8"BAN30", 8, {}, {}, {u8"BAN30:0", u8"BAN30:1", u8"BAN30:2"}});
d.cues.emplace(u8"BAN30:0", Cue{u8"BAN30:0", u8"BAN30", CueKind::Speech, u8"joe", u8"Mostra o corte. Eu cubro a porta enquanto voc\u00ea trata.", u8"", 15, {}, {}, {}, u8""});
d.cues.emplace(u8"BAN30:1", Cue{u8"BAN30:1", u8"BAN30", CueKind::Speech, u8"harley", u8"Voc\u00ea est\u00e1 com medo por mim.", u8"", 15, {}, {}, {}, u8""});
d.cues.emplace(u8"BAN30:2", Cue{u8"BAN30:2", u8"BAN30", CueKind::Speech, u8"joe", u8"Estou. N\u00e3o faz eu perder tempo negando.", u8"", 15, {}, {}, {}, u8""});
d.blocks.emplace(u8"BAN31", Block{u8"BAN31", 15, {}, {}, {u8"BAN31:0", u8"BAN31:1", u8"BAN31:2"}});
d.cues.emplace(u8"BAN31:0", Cue{u8"BAN31:0", u8"BAN31", CueKind::Speech, u8"bartholomeu", u8"Se voc\u00ea for pela frente, eu fecho atr\u00e1s. Mas me espera na v\u00e1lvula.", u8"", 15, {}, {}, {}, u8""});
d.cues.emplace(u8"BAN31:1", Cue{u8"BAN31:1", u8"BAN31", CueKind::Speech, u8"joe", u8"Voc\u00ea aguenta?", u8"", 15, {}, {}, {}, u8""});
d.cues.emplace(u8"BAN31:2", Cue{u8"BAN31:2", u8"BAN31", CueKind::Speech, u8"bartholomeu", u8"Com medo e tudo. Me espera.", u8"", 15, {}, {}, {}, u8""});
d.blocks.emplace(u8"BAN32", Block{u8"BAN32", 15, {}, {}, {u8"BAN32:0", u8"BAN32:1", u8"BAN32:2"}});
d.cues.emplace(u8"BAN32:0", Cue{u8"BAN32:0", u8"BAN32", CueKind::Speech, u8"jack", u8"Na primeira vez que cruzei com o morcego, fugi da rota que ele esperava. Ha.", u8"", 15, {}, {}, {}, u8"jack_previous_encounter_heard"});
d.cues.emplace(u8"BAN32:1", Cue{u8"BAN32:1", u8"BAN32", CueKind::Speech, u8"joe", u8"Parece que ele aprendeu seus truques.", u8"", 15, {}, {}, {}, u8""});
d.cues.emplace(u8"BAN32:2", Cue{u8"BAN32:2", u8"BAN32", CueKind::Speech, u8"jack", u8"E n\u00f3s aprendemos que ele pode aprender.", u8"", 15, {}, {}, {}, u8""});
d.blocks.emplace(u8"BAN33", Block{u8"BAN33", 8, {}, {}, {u8"BAN33:0", u8"BAN33:1", u8"BAN33:2"}});
d.cues.emplace(u8"BAN33:0", Cue{u8"BAN33:0", u8"BAN33", CueKind::Speech, u8"jack", u8"Sabe o que eu mais admiro nele? A pausa antes de abrir uma porta.", u8"", 15, {}, {}, {}, u8""});
d.cues.emplace(u8"BAN33:1", Cue{u8"BAN33:1", u8"BAN33", CueKind::Speech, u8"joe", u8"Voc\u00ea est\u00e1 sorrindo de novo.", u8"", 15, {}, {}, {}, u8""});
d.cues.emplace(u8"BAN33:2", Cue{u8"BAN33:2", u8"BAN33", CueKind::Speech, u8"jack", u8"Estou pensando numa sa\u00edda. Ha... ha.", u8"", 15, {}, {}, {}, u8""});
d.blocks.emplace(u8"BAN34", Block{u8"BAN34", 15, {}, {}, {u8"BAN34:0", u8"BAN34:1", u8"BAN34:2", u8"BAN34:3"}});
d.cues.emplace(u8"BAN34:0", Cue{u8"BAN34:0", u8"BAN34", CueKind::Speech, u8"jack", u8"A escada oeste \u00e9 mais curta.", u8"", 15, {}, {}, {}, u8""});
d.cues.emplace(u8"BAN34:1", Cue{u8"BAN34:1", u8"BAN34", CueKind::Speech, u8"harley", u8"E mais exposta. Barth, voc\u00ea viu o corredor?", u8"", 15, {}, {}, {}, u8""});
d.cues.emplace(u8"BAN34:2", Cue{u8"BAN34:2", u8"BAN34", CueKind::Speech, u8"bartholomeu", u8"Vi a porta aberta. N\u00e3o vi ele.", u8"", 15, {}, {}, {}, u8""});
d.cues.emplace(u8"BAN34:3", Cue{u8"BAN34:3", u8"BAN34", CueKind::Speech, u8"harley", u8"Pronto. Isso vale mais que certeza inventada.", u8"", 15, {}, {}, {}, u8""});
d.blocks.emplace(u8"BAN35", Block{u8"BAN35", 15, {}, {}, {u8"BAN35:0", u8"BAN35:1", u8"BAN35:2"}});
d.cues.emplace(u8"BAN35:0", Cue{u8"BAN35:0", u8"BAN35", CueKind::Speech, u8"bartholomeu", u8"Se voc\u00ea disser para eu ficar, eu fico. S\u00f3 n\u00e3o some sem falar.", u8"", 15, {}, {}, {}, u8""});
d.cues.emplace(u8"BAN35:1", Cue{u8"BAN35:1", u8"BAN35", CueKind::Speech, u8"joe", u8"Eu vou dizer o que decidi.", u8"", 15, {}, {}, {}, u8""});
d.cues.emplace(u8"BAN35:2", Cue{u8"BAN35:2", u8"BAN35", CueKind::Speech, u8"bartholomeu", u8"\u00c9 tudo que pe\u00e7o de um amigo.", u8"", 15, {}, {}, {}, u8""});
d.blocks.emplace(u8"BAN36", Block{u8"BAN36", 15, {}, {}, {u8"BAN36:0", u8"BAN36:1", u8"BAN36:2"}});
d.cues.emplace(u8"BAN36:0", Cue{u8"BAN36:0", u8"BAN36", CueKind::Speech, u8"harley", u8"Eu posso encontrar meu caminho. S\u00f3 me diz onde voc\u00ea pretende ir.", u8"", 15, {}, {}, {}, u8""});
d.cues.emplace(u8"BAN36:1", Cue{u8"BAN36:1", u8"BAN36", CueKind::Speech, u8"joe", u8"Pela janela, se a passagem estiver livre. Voc\u00ea quer tentar comigo?", u8"", 15, {}, {}, {}, u8""});
d.cues.emplace(u8"BAN36:2", Cue{u8"BAN36:2", u8"BAN36", CueKind::Speech, u8"harley", u8"\u00c9 disso que eu precisava: uma escolha de verdade.", u8"", 15, {}, {}, {}, u8""});
d.blocks.emplace(u8"BAN37", Block{u8"BAN37", 15, {}, {}, {u8"BAN37:0", u8"BAN37:1", u8"BAN37:2"}});
d.cues.emplace(u8"BAN37:0", Cue{u8"BAN37:0", u8"BAN37", CueKind::Speech, u8"bartholomeu", u8"Eu tremi a noite toda e ainda estou aqui.", u8"", 15, {}, {}, {}, u8""});
d.cues.emplace(u8"BAN37:1", Cue{u8"BAN37:1", u8"BAN37", CueKind::Speech, u8"joe", u8"Voc\u00ea tamb\u00e9m me trouxe at\u00e9 aqui.", u8"", 15, {}, {}, {}, u8""});
d.cues.emplace(u8"BAN37:2", Cue{u8"BAN37:2", u8"BAN37", CueKind::Speech, u8"bartholomeu", u8"Ent\u00e3o abre, amigo. Antes que eu comece de novo.", u8"", 15, {}, {}, {}, u8""});
d.blocks.emplace(u8"BAN38", Block{u8"BAN38", 15, {}, {}, {u8"BAN38:0", u8"BAN38:1", u8"BAN38:2"}});
d.cues.emplace(u8"BAN38:0", Cue{u8"BAN38:0", u8"BAN38", CueKind::Speech, u8"harley", u8"Se essa coisa pousar, a gente decide junto quem sobe.", u8"", 15, {}, {}, {}, u8""});
d.cues.emplace(u8"BAN38:1", Cue{u8"BAN38:1", u8"BAN38", CueKind::Speech, u8"joe", u8"Se n\u00e3o pousar, temos outra sa\u00edda.", u8"", 15, {}, {}, {}, u8""});
d.cues.emplace(u8"BAN38:2", Cue{u8"BAN38:2", u8"BAN38", CueKind::Speech, u8"harley", u8"Olha s\u00f3. Um plano inteiro. Estou orgulhosa.", u8"", 15, {}, {}, {}, u8""});
d.blocks.emplace(u8"BAN39", Block{u8"BAN39", 15, {}, {}, {u8"BAN39:0", u8"BAN39:1", u8"BAN39:2"}});
d.cues.emplace(u8"BAN39:0", Cue{u8"BAN39:0", u8"BAN39", CueKind::Speech, u8"bartholomeu", u8"O ar vem dali. N\u00e3o digo que \u00e9 seguro; digo que n\u00e3o acaba aqui.", u8"", 15, {}, {}, {}, u8""});
d.cues.emplace(u8"BAN39:1", Cue{u8"BAN39:1", u8"BAN39", CueKind::Speech, u8"joe", u8"Foi por isso que te trouxe.", u8"", 15, {}, {}, {}, u8""});
d.cues.emplace(u8"BAN39:2", Cue{u8"BAN39:2", u8"BAN39", CueKind::Speech, u8"bartholomeu", u8"Voc\u00ea me trouxe porque somos amigos. Eu encontrei o ar sozinho.", u8"", 15, {}, {}, {}, u8""});
d.blocks.emplace(u8"BAN40", Block{u8"BAN40", 15, {}, {}, {u8"BAN40:0", u8"BAN40:1", u8"BAN40:2"}});
d.cues.emplace(u8"BAN40:0", Cue{u8"BAN40:0", u8"BAN40", CueKind::Speech, u8"joe", u8"Voc\u00ea consegue atravessar?", u8"", 15, {}, {}, {}, u8""});
d.cues.emplace(u8"BAN40:1", Cue{u8"BAN40:1", u8"BAN40", CueKind::Speech, u8"harley", u8"Consigo decidir. Me diz quanto tempo temos.", u8"", 15, {}, {}, {}, u8""});
d.cues.emplace(u8"BAN40:2", Cue{u8"BAN40:2", u8"BAN40", CueKind::Speech, u8"joe", u8"Pouco. Mas vou esperar sua resposta.", u8"", 15, {}, {}, {}, u8""});
d.blocks.emplace(u8"BAN41", Block{u8"BAN41", 8, {}, {}, {u8"BAN41:0", u8"BAN41:1", u8"BAN41:2"}});
d.cues.emplace(u8"BAN41:0", Cue{u8"BAN41:0", u8"BAN41", CueKind::Speech, u8"jack", u8"Ele quase me pegou uma vez. Ainda rio quando lembro. Ha...", u8"", 15, {}, {}, {}, u8"jack_previous_encounter_heard"});
d.cues.emplace(u8"BAN41:1", Cue{u8"BAN41:1", u8"BAN41", CueKind::Speech, u8"joe", u8"Voc\u00ea ri como se tivesse gostado.", u8"", 15, {}, {}, {}, u8""});
d.cues.emplace(u8"BAN41:2", Cue{u8"BAN41:2", u8"BAN41", CueKind::Speech, u8"jack", u8"Talvez eu goste de chegar ao fim da hist\u00f3ria.", u8"", 15, {}, {}, {}, u8""});
d.blocks.emplace(u8"BAN42", Block{u8"BAN42", 15, {}, {}, {u8"BAN42:0", u8"BAN42:1", u8"BAN42:2"}});
d.cues.emplace(u8"BAN42:0", Cue{u8"BAN42:0", u8"BAN42", CueKind::Speech, u8"harley", u8"Se sairmos daqui, n\u00e3o quero que finja que esta noite n\u00e3o aconteceu.", u8"", 15, {}, {}, {}, u8""});
d.cues.emplace(u8"BAN42:1", Cue{u8"BAN42:1", u8"BAN42", CueKind::Speech, u8"joe", u8"N\u00e3o vou esquecer o Thomas.", u8"", 15, {}, {}, {}, u8""});
d.cues.emplace(u8"BAN42:2", Cue{u8"BAN42:2", u8"BAN42", CueKind::Speech, u8"harley", u8"Nem ele, nem as pessoas que ainda est\u00e3o aqui.", u8"", 15, {}, {}, {}, u8""});
